-- Run ONLY on staging. All synthetic users, settings and rows are rolled back.
begin;
do $$
declare buyer uuid:=gen_random_uuid(); other_user uuid:=gen_random_uuid(); reviewer uuid:=gen_random_uuid();
 account uuid; product uuid; oid uuid; second_id uuid; rejected_id uuid; result jsonb; body jsonb;
begin
 insert into auth.users(id,aud,role) values(buyer,'authenticated','authenticated'),(other_user,'authenticated','authenticated'),(reviewer,'authenticated','authenticated');
 insert into mela_payments.reviewers(user_id) values(reviewer);
 insert into mela_payments.accounts(provider,recipient,label,active) values('telebirr','TEST-RECEIVER-NOT-REAL','TEST ONLY',true) returning id into account;
 insert into mela_payments.products(title,amount_minor,active) values('TEST ONLY',10000,true) returning id into product;
 perform set_config('request.jwt.claims','{}',true);
 begin perform public.payment_command_v1('catalog'); raise exception 'FAIL: unauthenticated accepted'; exception when insufficient_privilege then null; end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',buyer,'aal','aal1','role','authenticated')::text,true);
 begin perform public.payment_command_v1('create_order',jsonb_build_object('account_id',account,'product_id',product)); raise exception 'FAIL: disabled payments accepted'; exception when raise_exception then if sqlerrm<>'Payment collection is not enabled' then raise; end if; end;
 update mela_payments.settings set enabled=true;
 result:=public.payment_command_v1('create_order',jsonb_build_object('account_id',account,'product_id',product,'amount_minor',1,'user_id',other_user));
 oid:=(result->>'id')::uuid;
 if result->>'amount_minor'<>'10000' or (result->>'user_id')::uuid<>buyer then raise exception 'FAIL: client controls order'; end if;
 result:=public.payment_command_v1('submit',jsonb_build_object('order_id',oid,'reference',' test-001 '));
 if result->>'status'<>'pending' then raise exception 'FAIL: unverified approved'; end if;
 if (select reference from mela_payments.orders where id=oid)<>'TEST-001' then raise exception 'FAIL: normalization'; end if;
 begin perform public.payment_command_v1('submit',jsonb_build_object('order_id',oid,'reference','<script>')); raise exception 'FAIL: invalid reference'; exception when raise_exception then if sqlerrm not like 'Enter a valid%' then raise; end if; end;
 begin perform public.payment_command_v1('admin_queue'); raise exception 'FAIL: buyer has admin'; exception when insufficient_privilege then null; end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',other_user,'aal','aal1','role','authenticated')::text,true);
 begin perform public.payment_command_v1('submit',jsonb_build_object('order_id',oid,'reference','TEST-001')); raise exception 'FAIL: cross-account'; exception when insufficient_privilege then null; end;
 if jsonb_array_length(public.payment_command_v1('my_orders'))<>0 then raise exception 'FAIL: order privacy'; end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',reviewer,'aal','aal1','role','authenticated')::text,true);
 begin perform public.payment_command_v1('admin_queue'); raise exception 'FAIL: no MFA'; exception when insufficient_privilege then null; end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',reviewer,'aal','aal2','role','authenticated')::text,true);
 body:=jsonb_build_object('order_id',oid,'reference','TEST-001','recipient','TEST-RECEIVER-NOT-REAL','currency','ETB','amount_minor',10000,'paid_at',now(),'confirmed_received',true,'confirmed_order_owner',true,'evidence_note','TEST ONLY: verified receiving history and payer ownership');
 begin perform public.payment_command_v1('admin_record',body||'{"confirmed_received":false}'::jsonb); raise exception 'FAIL: unconfirmed accepted'; exception when raise_exception then if sqlerrm not like 'Confirm receipt%' then raise; end if; end;
 begin perform public.payment_command_v1('admin_record',body||'{"confirmed_order_owner":false}'::jsonb); raise exception 'FAIL: owner unconfirmed'; exception when raise_exception then if sqlerrm not like 'Confirm receipt%' then raise; end if; end;
 begin perform public.payment_command_v1('admin_record',body||'{"amount_minor":9999}'::jsonb); raise exception 'FAIL: underpayment'; exception when raise_exception then if sqlerrm not like 'Payment amount%' then raise; end if; end;
 begin perform public.payment_command_v1('admin_record',body||'{"recipient":"WRONG-ACCOUNT"}'::jsonb); raise exception 'FAIL: recipient mismatch'; exception when raise_exception then if sqlerrm not like 'Payment amount%' then raise; end if; end;
 begin perform public.payment_command_v1('admin_record',body||'{"currency":"USD"}'::jsonb); raise exception 'FAIL: currency mismatch'; exception when raise_exception then if sqlerrm not like 'Payment amount%' then raise; end if; end;
 begin perform public.payment_command_v1('admin_record',body||jsonb_build_object('paid_at',now()+interval '1 day')); raise exception 'FAIL: future date'; exception when raise_exception then if sqlerrm<>'Invalid payment date' then raise; end if; end;
 begin perform public.payment_command_v1('admin_record',body||jsonb_build_object('paid_at',now()-interval '1 day')); raise exception 'FAIL: old receipt'; exception when raise_exception then if sqlerrm<>'Invalid payment date' then raise; end if; end;
 result:=public.payment_command_v1('admin_record',body);
 if result->>'status'<>'approved' then raise exception 'FAIL: valid payment not approved'; end if;
 perform public.payment_command_v1('admin_record',body);
 perform public.payment_command_v1('admin_recheck',jsonb_build_object('order_id',oid));
 if (select count(*) from mela_payments.entitlements where order_id=oid)<>1 then raise exception 'FAIL: double grant'; end if;
 if (select count(*) from mela_payments.audit where order_id=oid and action='agent_approved')<>1 then raise exception 'FAIL: duplicate approval audit'; end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',buyer,'aal','aal1','role','authenticated')::text,true);
 result:=public.payment_command_v1('create_order',jsonb_build_object('account_id',account,'product_id',product)); second_id:=(result->>'id')::uuid;
 result:=public.payment_command_v1('submit',jsonb_build_object('order_id',second_id,'reference','TEST-001'));
 if result->>'status'<>'pending' then raise exception 'FAIL: stolen/used reference approved'; end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',reviewer,'aal','aal2','role','authenticated')::text,true);
 begin perform public.payment_command_v1('admin_record',body||jsonb_build_object('order_id',second_id)); raise exception 'FAIL: duplicate receipt accepted'; exception when unique_violation then null; end;
 result:=public.payment_command_v1('admin_reject',jsonb_build_object('order_id',second_id,'reason','Duplicate reference: no matching new incoming payment'));
 if result->>'status'<>'rejected' then raise exception 'FAIL: reject'; end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',buyer,'aal','aal1','role','authenticated')::text,true);
 result:=public.payment_command_v1('submit',jsonb_build_object('order_id',second_id,'reference','NEW-REF-001'));
 if result->>'status'<>'rejected' then raise exception 'FAIL: terminal state reopened'; end if;
 result:=public.payment_command_v1('create_order',jsonb_build_object('account_id',account,'product_id',product)); rejected_id:=(result->>'id')::uuid;
 update mela_payments.orders set expires_at=now()-interval '1 second' where id=rejected_id;
 begin perform public.payment_command_v1('submit',jsonb_build_object('order_id',rejected_id,'reference','EXPIRED-001')); raise exception 'FAIL: expired submitted'; exception when raise_exception then if sqlerrm not like 'Order expired%' then raise; end if; end;
 if has_function_privilege('anon','public.payment_command_v1(text,jsonb)','EXECUTE') then raise exception 'FAIL: anon execute'; end if;
 if has_function_privilege('authenticated','mela_payments.reconcile(uuid)','EXECUTE') then raise exception 'FAIL: internal reconcile exposed'; end if;
 if has_table_privilege('authenticated','mela_payments.receipts','INSERT') then raise exception 'FAIL: receipt writable'; end if;
 if has_table_privilege('authenticated','mela_payments.orders','UPDATE') then raise exception 'FAIL: order writable'; end if;
 if has_table_privilege('authenticated','mela_payments.entitlements','INSERT') then raise exception 'FAIL: entitlement writable'; end if;
 if exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='mela_payments' and c.relkind='r' and not c.relrowsecurity) then raise exception 'FAIL: RLS missing'; end if;
end $$;
select 'PASS: authorization, isolation, trusted record matching, replay protection, idempotency, rejection, expiry, server price and permissions' as payment_tests;
rollback;
